#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Texturing : 4
COMPONENT TextureProjection : 2
COMPONENT CubeMapTexturing : 3
COMPONENT Layering : 1
COMPONENT Layout : 2
COMPONENT Lighting : 3
COMPONENT EnvironmentalEffects : 4
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1
COMPONENT Picking : 3

Viewpoint {
  position 0 0 14
}

Background {
  skyColor 0.1 0.1 0.2
}

DEF SPIN Transform {
  translation 0 2.5 -2
  rotation 0 0.999999999999999 0 0.523598395751119
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.9 0.6 0.1
      }
    }
    geometry Box {
      size 1.5 1.5 1.5
    }
  }
}

DEF TS TimeSensor {
  cycleInterval 4
  loop TRUE
}

DEF OI OrientationInterpolator {
  key [
    0,
    0.5,
    1
  ]
  keyValue [
    0 1 0 0,
    0 1 0 3.14159,
    0 1 0 6.28318
  ]
}

DEF RT RenderedTexture {
  singleFrame FALSE
  updateInterval 0.2
}

Transform {
  translation -3 -2 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 1 1
      }
      texture USE RT
    }
    geometry IndexedFaceSet {
      solid FALSE
      coordIndex [
        0,
        1,
        2,
        3,
        -1
      ]
      texCoord TextureCoordinate {
        point [
          0 0,
          1 0,
          1 1,
          0 1
        ]
      }
      coord Coordinate {
        point [
          -1.3 -1.3 0,
          1.3 -1.3 0,
          1.3 1.3 0,
          -1.3 1.3 0
        ]
      }
    }
  }
}

DEF RT2 RenderedTexture {
  width 96
  height 96
  children [
    DEF V2 Viewpoint {
      position 0 0 6
    }
    DEF B2 Background {
      skyColor 0.2 0.5 0.2
    }
    USE SPIN
  ]
}

Transform {
  translation 0.5 -2 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 1 1
      }
      texture USE RT2
    }
    geometry IndexedFaceSet {
      solid FALSE
      coordIndex [
        0,
        1,
        2,
        3,
        -1
      ]
      texCoord TextureCoordinate {
        point [
          0 0,
          1 0,
          1 1,
          0 1
        ]
      }
      coord Coordinate {
        point [
          -1.3 -1.3 0,
          1.3 -1.3 0,
          1.3 1.3 0,
          -1.3 1.3 0
        ]
      }
    }
  }
}

DEF P TextureProjector {
  location 3.6 -2 4
  direction 0 0 -1
  fieldOfView 0.5
  texture USE RT2
}

Transform {
  translation 3.6 -2 -0.5
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 1 1
      }
    }
    geometry Box {
      size 2.4 2.4 0.2
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOnly      SFFloat  on_aspect
  inputOutput    SFString log "A1.0000 A1.0000 "
  initializeOnly SFNode   rt USE RT
  initializeOnly SFNode   rt2 USE RT2
  initializeOnly SFNode   b2 USE B2

  url "javascript:
function on_aspect (value) { log = log + 'A' + value .toFixed (4) + ' '; }
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') rt2 .singleFrame = false;
   if (k == 'b') { rt2 .singleFrame = true; rt2 .width = 160; rt2 .height = 64; }
   if (k == 'c') rt .singleFrame = true;
   if (k == 'd') b2 .transparency = 0.5;
   if (k == 'e') rt2 .children = new MFNode ();
   if (k == 'f') rt2 .depthMap = true;
   if (k == 'g') rt2 .width = 0;
   if (k == 'h') { rt2 .depthMap = false; rt2 .width = 64; rt2 .height = 128; }
   if (k == 'i') rt .updateInterval = 0;
   if (k == 'j') rt .singleFrame = false;
}
"
  directOutput TRUE
}

ROUTE TS.fraction_changed TO OI.set_fraction
ROUTE OI.value_changed TO SPIN.set_rotation
ROUTE K.keyPress TO R.on_key
ROUTE P.aspectRatio TO R.on_aspect

